const std = @import("std");
const math = std.math;
const d_model: usize = 18432;
const grid_size: usize = 5;

pub const NeuralState = struct {
    potential: f64,
    quantum_phase: f64,
    lorenz_params: [3]f64,
    spline_coeffs: [d_model][grid_size]f64,
};

pub fn update_state(state: *NeuralState, token_embedding: []const f64, grid_val: usize) void {
    var sum_emb: f64 = 0.0;
    for (token_embedding) |emb| {
        sum_emb += emb;
    }
    if (grid_val > 0) {
        const d_model_float: f64 = @floatFromInt(d_model);
        const grid_float: f64 = @floatFromInt(grid_val);
        const product: f64 = d_model_float * grid_float;
        if (product > 0.0) {
            const log_val: f64 = @log(product);
            state.potential += sum_emb * 0.01 * log_val;
        }
    }
    state.quantum_phase += math.pi / 180.0;
}

fn clamp(value: f64, min_val: f64, max_val: f64) f64 {
    if (value < min_val) {
        return min_val;
    } else if (value > max_val) {
        return max_val;
    } else {
        return value;
    }
}

fn b_spline_basis_cox_de_boor(x: f64, knots: []const f64, i: usize, p: usize) f64 {
    if (p == 0) {
        if (i + 1 >= knots.len) {
            return 0.0;
        }
        if (i == knots.len - 2) {
            if (x >= knots[i] and x <= knots[i + 1]) {
                return 1.0;
            } else {
                return 0.0;
            }
        } else {
            if (x >= knots[i] and x < knots[i + 1]) {
                return 1.0;
            } else {
                return 0.0;
            }
        }
    }
    var left_term: f64 = 0.0;
    var right_term: f64 = 0.0;
    if (i + p < knots.len) {
        const denom_left = knots[i + p] - knots[i];
        if (denom_left != 0.0) {
            const basis_left = b_spline_basis_cox_de_boor(x, knots, i, p - 1);
            left_term = ((x - knots[i]) / denom_left) * basis_left;
        }
    }
    if (i + 1 < knots.len and i + p + 1 < knots.len) {
        const denom_right = knots[i + p + 1] - knots[i + 1];
        if (denom_right != 0.0) {
            const basis_right = b_spline_basis_cox_de_boor(x, knots, i + 1, p - 1);
            right_term = ((knots[i + p + 1] - x) / denom_right) * basis_right;
        }
    }
    return left_term + right_term;
}

pub fn kan_spline_eval(x: f64, coeffs: [grid_size]f64, g: usize) f64 {
    if (g == 0 or g > grid_size) {
        return 0.0;
    }
    const degree: usize = 3;
    if (g < degree + 1) {
        return 0.0;
    }
    const num_control_points = g;
    const num_knots = num_control_points + degree + 1;
    var knots_array: [grid_size + 4]f64 = undefined;
    for (0..num_knots) |i| {
        if (i <= degree) {
            knots_array[i] = 0.0;
        } else if (i >= num_control_points) {
            knots_array[i] = 1.0;
        } else {
            const interior_index = i - degree;
            const denom = num_control_points - degree;
            if (denom > 0) {
                knots_array[i] = @as(f64, @floatFromInt(interior_index)) / @as(f64, @floatFromInt(denom));
            } else {
                knots_array[i] = 0.0;
            }
        }
    }
    var sum: f64 = 0.0;
    const x_clamped = clamp(x, 0.0, 1.0);
    for (0..num_control_points) |i| {
        const basis_val = b_spline_basis_cox_de_boor(x_clamped, knots_array[0..num_knots], i, degree);
        sum += basis_val * coeffs[i];
    }
    return sum;
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();

    var state: NeuralState = undefined;
    state.potential = 0.0;
    state.quantum_phase = 0.0;
    state.lorenz_params[0] = 10.0;
    state.lorenz_params[1] = 28.0;
    state.lorenz_params[2] = 8.0 / 3.0;

    for (0..d_model) |i| {
        for (0..grid_size) |j| {
            state.spline_coeffs[i][j] = 0.0;
        }
    }

    var token_emb: [d_model]f64 = undefined;
    for (0..d_model) |i| {
        token_emb[i] = 0.0;
    }

    update_state(&state, token_emb[0..], grid_size);

    const spline_result = kan_spline_eval(0.5, state.spline_coeffs[0], grid_size);

    const stdout = std.io.getStdOut().writer();
    try stdout.print("Quantum Zig Loaded for JAIDE V33\n", .{});
    try stdout.print("Spline evaluation result: {d}\n", .{spline_result});
}

